<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><section class="sd-dashboard-card"><div class="sd-card-heading"><h2><?php esc_html_e( 'My communities', 'social-discovery' ); ?></h2><a href="<?php echo esc_url( sd_home_url( 'my-communities' ) ); ?>"><?php esc_html_e( 'View all', 'social-discovery' ); ?></a></div><?php if ( function_exists( 'groups_get_user_groups' ) ) : $groups = groups_get_user_groups( get_current_user_id() ); if ( ! empty( $groups['groups'] ) ) : ?><ul class="sd-dashboard-list"><?php foreach ( array_slice( $groups['groups'], 0, 4 ) as $group ) : ?><li><a href="<?php echo esc_url( sd_group_url( $group->id ) ); ?>"><strong><?php echo esc_html( bp_get_group_name( $group ) ); ?></strong><small><?php echo esc_html( ucfirst( $group->status ) ); ?></small></a></li><?php endforeach; ?></ul><?php else : ?><p class="sd-muted"><?php esc_html_e( 'You have not joined a community yet.', 'social-discovery' ); ?></p><?php endif; else : ?><p class="sd-muted"><?php esc_html_e( 'Communities become available when BuddyPress Groups is active.', 'social-discovery' ); ?></p><?php endif; ?></section>
